<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;600;800&family=Archivo+Narrow:wght@400;700&display=swap" rel="stylesheet">
<style>
  :root{
    --red:#e33127;
    --blue:#1f4fa3;
    --yellow:#f2c53d;
    --black:#111111;
    --white:#f7f5f0;
    --grey:#d8d5cd;
    --line:10px;
  }
  *{margin:0;padding:0;box-sizing:border-box;}
  html{scroll-behavior:smooth;}
  body{
    font-family:'Archivo',sans-serif;
    background:var(--white);
    color:var(--black);
    line-height:1.55;
  }

  /* ---------- header: a Mondrian composition ---------- */
  .hero{
    display:grid;
    grid-template-columns: 3fr 1fr 2fr;
    grid-template-rows: auto auto auto;
    gap:var(--line);
    background:var(--black);
    padding:var(--line);
    min-height:88vh;
    align-content:stretch;
  }
  .cell{
    display:flex;
    flex-direction:column;
    justify-content:center;
    align-items:flex-start;
    padding:2.2rem 1.8rem;
    background:var(--white);
  }
  .cell.red{background:var(--red);color:var(--white);}
  .cell.blue{background:var(--blue);color:var(--white);}
  .cell.yellow{background:var(--yellow);color:var(--black);}
  .cell.grey{background:var(--grey);}

  .cell .kicker{
    font-family:'Archivo Narrow',sans-serif;
    font-weight:700;
    text-transform:uppercase;
    letter-spacing:.18em;
    font-size:.8rem;
    margin-bottom:.6rem;
    opacity:.85;
  }
  .cell h1{
    font-weight:800;
    font-size:clamp(1.6rem,3.4vw,2.6rem);
    line-height:1.08;
    text-transform:uppercase;
    letter-spacing:.01em;
  }
  .cell .sub{
    margin-top:.7rem;
    font-size:1.02rem;
    max-width:34ch;
  }
  .cell .big{
    font-weight:800;
    font-size:clamp(2.6rem,6vw,4.6rem);
    line-height:1;
  }
  .cell .label{
    font-family:'Archivo Narrow',sans-serif;
    font-weight:700;
    text-transform:uppercase;
    letter-spacing:.14em;
    font-size:.85rem;
  }

  /* hero grid layout, mirroring the painting:
     large red top-right, small blue bottom-left, small yellow bottom-right */
  .c1{grid-column:1;grid-row:1/3;}
  .c2{grid-column:2;grid-row:1;}
  .c3{grid-column:3;grid-row:1;}
  .c4{grid-column:1;grid-row:3;}
  .c5{grid-column:2;grid-row:2/4;}
  .c6{grid-column:3;grid-row:2/4;}

  /* ---------- content sections ---------- */
  section.block{
    display:grid;
    grid-template-columns:var(--line) 1fr var(--line);
    background:var(--black);
  }
  .block .side{background:var(--black);}
  .block .inner{
    background:var(--white);
    padding:3.2rem 2.4rem;
  }
  .block h2{
    font-weight:800;
    text-transform:uppercase;
    font-size:clamp(1.3rem,2.6vw,2rem);
    letter-spacing:.02em;
    margin-bottom:1.1rem;
    display:flex;
    align-items:center;
    gap:.8rem;
  }
  .block h2 .swatch{
    width:1.1rem;height:1.1rem;display:inline-block;flex:none;
  }
  .block p{max-width:62ch;margin-bottom:.9rem;}
  .block p:last-child{margin-bottom:0;}
  .block strong{font-weight:600;}

  .facts{
    display:grid;
    grid-template-columns:repeat(auto-fit,minmax(220px,1fr));
    gap:var(--line);
    margin-top:1.4rem;
    background:var(--black);
    padding:var(--line);
  }
  .fact{
    background:var(--white);
    padding:1.1rem 1.2rem;
  }
  .fact .k{
    font-family:'Archivo Narrow',sans-serif;
    font-weight:700;text-transform:uppercase;letter-spacing:.14em;
    font-size:.72rem;opacity:.7;display:block;margin-bottom:.3rem;
  }
  .fact .v{font-weight:600;font-size:1.02rem;}

